%[text] BME 5910 - HW 1
%[text] Problems 1.9
%[text] Author: Garrett Kunkler
%[text] Aids: 
%[text] - Textbook: Biomedical Optics: Principles and Imaging by Lihong Wang and Hsin-I Wu
%[text] - Data: https://omlc.org/spectra/hemoglobin/summary.html
%[text] - Copilot: Formatting data table \
% Data
data = load("hemoglobin_data.mat").data;

lambda = data(:,1);
epsilon_ox = data(:,2);
epsilon_de = data(:,3);
%%
% Plotting
plot(lambda, epsilon_ox, 'r-', 'DisplayName','HbO2') %[output:7f072213]
hold on %[output:7f072213]
plot(lambda, epsilon_de, 'b--', 'DisplayName','Hb') %[output:7f072213]
hold off %[output:7f072213]
yscale("log") %[output:7f072213]
xlim([min(lambda), max(lambda)]) %[output:7f072213]
xlabel("Wavelength [nm]") %[output:7f072213]
ylabel("Molar extinction coefficient [1/cm-M]") %[output:7f072213]
title("Oxygenated and Deoxygenated Hemoglobin Extinction") %[output:7f072213]
legend("Location","northeast") %[output:7f072213]

